      a: "<p>YouTube shows you <em>one pattern</em> in 12 minutes of fluff. This bundle hands you <strong>320 patterns</strong> in one folder, each with an MP3 preview so you can find the right vibe in seconds. No talking, no ads, no missing details.</p><p>One Drake hit transcription on Fiverr costs €30+. You're getting 320 of them for €27.</p>" }
  ];

  function build() {
    // Find or create mount
    var mount = document.getElementById('fbFaqMount');
    if (!mount) {
      mount = document.createElement('div');
