      var sc = document.currentScript || (function(){ var s = document.getElementsByTagName('script'); return s[s.length-1]; })();
      if (sc && sc.parentNode) sc.parentNode.insertBefore(mount, sc);
      else document.body.appendChild(mount);
    }

    // Inject styles once
    if (!document.getElementById('fbFaqStyles')) {
      var fontLink = document.createElement('link');
      fontLink.rel = 'stylesheet';
      fontLink.href = 'https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;500;700;800&display=swap';
      document.head.appendChild(fontLink);

      var style = document.createElement('style');
      style.id = 'fbFaqStyles';
      style.innerHTML =
        ".fb-faq{--fb-ink:#0a0a0a;--fb-ink-soft:#2a2a2a;--fb-line:#e6e6e8;--fb-card:#fff;--fb-accent:#e63946;box-sizing:border-box;width:100%;max-width:820px;margin:0 auto;padding:20px 0;color:#0a0a0a;font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased;line-height:1.5}" +
        ".fb-faq *,.fb-faq *::before,.fb-faq *::after{box-sizing:border-box}" +
        ".fb-faq button{font-family:inherit}" +
        ".fb-faq-eyebrow{text-align:center;color:#e63946;font-size:12px;font-weight:800;letter-spacing:0.22em;text-transform:uppercase;margin:0 0 10px}" +
        ".fb-faq-title{font-family:'Anton','Bebas Neue',Impact,sans-serif;font-weight:400;font-size:clamp(36px,7vw,60px);line-height:0.95;letter-spacing:0.005em;margin:0 0 12px;text-align:center;text-transform:uppercase;color:#0a0a0a}" +
        ".fb-faq-title em{font-style:normal;color:#e63946;position:relative;display:inline-block}" +
        ".fb-faq-title em::after{content:'';position:absolute;left:0;right:0;bottom:4%;height:6px;background:#e63946;opacity:0.18;z-index:-1}" +
        ".fb-faq-subtitle{text-align:center;color:#2a2a2a;opacity:0.75;font-size:clamp(15px,2vw,17px);margin:0 auto 32px;max-width:520px}" +
        ".fb-faq-list{display:flex !important;flex-direction:column !important;gap:12px;width:100% !important}" +
        ".fb-faq-item{background:#fff;border:2px solid #0a0a0a;border-radius:8px;box-shadow:3px 3px 0 #0a0a0a;overflow:hidden;transition:box-shadow 0.15s,border-color 0.15s;width:100% !important;display:block !important}" +
        ".fb-faq-item.is-open{border-color:#e63946;box-shadow:3px 3px 0 #e63946}" +
        ".fb-faq-trigger{width:100%;display:flex !important;align-items:center;justify-content:space-between;gap:16px;padding:18px 22px;background:transparent;border:none;cursor:pointer;text-align:left !important;font-size:16px;font-weight:700;color:#0a0a0a;line-height:1.35;transition:background 0.15s;font-family:inherit}" +
        ".fb-faq-trigger:hover{background:rgba(230,57,70,0.04)}" +
        ".fb-faq-trigger:focus{outline:none;background:rgba(230,57,70,0.04)}" +
        ".fb-faq-icon{flex-shrink:0;width:28px;height:28px;border-radius:50%;background:#0a0a0a;color:#fff;position:relative;transition:background 0.2s,transform 0.25s ease;display:inline-block}" +
        ".fb-faq-icon::before,.fb-faq-icon::after{content:'';position:absolute;top:50%;left:50%;background:#fff;border-radius:1px;transition:transform 0.25s ease}" +
        ".fb-faq-icon::before{width:12px;height:2px;transform:translate(-50%,-50%)}" +
        ".fb-faq-icon::after{width:2px;height:12px;transform:translate(-50%,-50%)}" +
        ".fb-faq-item.is-open .fb-faq-icon{background:#e63946;transform:rotate(180deg)}" +
        ".fb-faq-item.is-open .fb-faq-icon::after{transform:translate(-50%,-50%) scaleY(0)}" +
        ".fb-faq-panel{overflow:hidden;height:0;transition:height 0.28s ease}" +
        ".fb-faq-panel-inner{padding:18px 22px 22px;color:#2a2a2a;font-size:15.5px;line-height:1.6;border-top:1px solid #e6e6e8}" +
        ".fb-faq-panel-inner p{margin:0 0 12px}" +
        ".fb-faq-panel-inner p:last-child{margin-bottom:0}" +
        ".fb-faq-panel-inner strong{color:#0a0a0a;font-weight:700}" +
        ".fb-faq-cta{text-align:center;margin-top:36px;padding:24px 20px;border:2px dashed #0a0a0a;background:rgba(0,0,0,0.03);border-radius:8px}" +
        ".fb-faq-cta-text{color:#2a2a2a;margin:0 0 6px;font-size:15px;font-weight:500}" +
        ".fb-faq-cta-link{display:inline-block;color:#e63946;text-decoration:none;font-weight:800;font-size:17px;letter-spacing:0.01em;border-bottom:2px solid transparent;transition:border-color 0.15s}" +
        ".fb-faq-cta-link:hover{border-bottom-color:#e63946}" +
        "@media (max-width:540px){.fb-faq{padding:16px 0}.fb-faq-subtitle{padding:0 12px;margin-bottom:24px}.fb-faq-trigger{padding:16px 18px;font-size:15px;gap:12px}.fb-faq-icon{width:26px;height:26px}.fb-faq-panel-inner{padding:16px 18px 18px;font-size:14.5px}.fb-faq-cta{margin-top:28px;padding:20px 16px}}";
      document.head.appendChild(style);
    }

    function escapeHtml(s) {
      return String(s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
      });
    }

    var itemsHtml = '';
    for (var i = 0; i < FAQS.length; i++) {
      itemsHtml += '<div class="fb-faq-item">' +
        '<button type="button" class="fb-faq-trigger" aria-expanded="false">' +
          '<span>' + escapeHtml(FAQS[i].q) + '</span>' +
          '<span class="fb-faq-icon" aria-hidden="true"></span>' +
        '</button>' +
        '<div class="fb-faq-panel">' +
          '<div class="fb-faq-panel-inner">' + FAQS[i].a + '</div>' +
        '</div>' +
      '</div>';
